<div class="theme-switch" role="radiogroup" aria-label="Colour theme" data-theme-switch>
  <button type="button" role="radio" data-theme-set="light" aria-checked="false" title="Light"><?= icon('sun', 'icon-sm') ?><span class="sr-only">Light</span></button>
  <button type="button" role="radio" data-theme-set="dark" aria-checked="false" title="Dark"><?= icon('moon', 'icon-sm') ?><span class="sr-only">Dark</span></button>
  <button type="button" role="radio" data-theme-set="system" aria-checked="true" title="Match my device"><?= icon('laptop', 'icon-sm') ?><span class="sr-only">System</span></button>
</div>
